def semver_sort(versions):
    def parse(v):
        # split off build metadata
        main = v.split('+', 1)[0]
        if '-' in main:
            core, pre = main.split('-', 1)
        else:
            core, pre = main, None
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is None:
            has_pre = 1  # no prerelease sorts after
            pre_ids = []
        else:
            has_pre = 0  # has prerelease sorts before
            pre_ids = []
            for ident in pre.split('.'):
                if ident.isdigit():
                    pre_ids.append((0, int(ident)))
                else:
                    pre_ids.append((1, ident))
        return (major, minor, patch, has_pre, pre_ids)

    keyed = [(parse(v), i, v) for i, v in enumerate(versions)]
    keyed.sort(key=lambda t: (t[0][0], t[0][1], t[0][2], t[0][3], t[0][4], t[1]))
    return [v for _, _, v in keyed]

